import numpy as np
rng=np.random.default_rng(7)

def rotz(v, deg):
    t=np.radians(deg); c,s=np.cos(t),np.sin(t)
    R=np.array([[c,-s,0],[s,c,0],[0,0,1.0]]); return R@np.array(v,float)
def unit(v):
    v=np.array(v,float); return v/np.linalg.norm(v)
def three_dirs(u,phi0=0.0):
    u=unit(u)
    a=np.array([1.0,0,0]) if abs(u[0])<0.9 else np.array([0,1.0,0])
    p1=unit(np.cross(u,a)); p2=np.cross(u,p1)
    return [unit(-u/3.0+np.sqrt(8.0)/3.0*(np.cos(np.radians(p))*p1+np.sin(np.radians(p))*p2))
            for p in (phi0,phi0+120,phi0+240)]

base=[]
def addb(el,xyz): base.append((el,np.array(xyz,float))); return len(base)-1
iCo2=addb('Co',(0,0,0)); iCo1=addb('Co',(0,0,2.40)); iNbot=addb('N',(0,0,-2.15))
N_loc=(1.98,0,0.0); P_loc=(2.08,0,1.72)
ring_loc=[(2.418,0,-1.404),(1.435,0,-2.471),(1.868,0,-3.855),
          (3.284,0,-4.173),(4.266,0,-3.106),(3.833,0,-1.721)]
d3_loc=(0.475,0.814,0.333); d4_loc=(0.475,-0.814,0.333)
constraints=[(iCo1,iCo2,2.40),(iCo2,iNbot,2.15)]
groups=[]
for theta in (0,120,240):
    iN=addb('N',rotz(N_loc,theta)); iP=addb('P',rotz(P_loc,theta))
    constraints+=[(iCo2,iN,1.98),(iCo1,iP,2.20),(iN,iP,1.72)]
    cs=[rotz(c,theta) for c in ring_loc]
    for p in cs: addb('C',p)
    rc=np.mean(cs,axis=0)
    for k in (2,3,4,5): addb('H',cs[k]+1.08*unit(cs[k]-rc))
    groups.append((iP,unit(rotz(d3_loc,theta))))
    groups.append((iP,unit(rotz(d4_loc,theta))))

def build_ipr_atoms(iP,d,phi0):
    Pp=base[iP][1]; CH=Pp+1.85*d
    ds=three_dirs(-d,phi0)
    items=[('C',CH),('H',CH+1.09*ds[0])]
    for dd in (ds[1],ds[2]):
        M=CH+1.54*dd; items.append(('C',M))
        for hd in three_dirs(-dd,phi0): items.append(('H',M+1.09*hd))
    return items

def lim(e1,e2):
    if e1=='H' and e2=='H': return 1.5
    if e1=='H' or e2=='H': return 1.8
    return 2.2
def clash(items, others):
    s=0.0
    for (e1,p1) in items:
        for (e2,p2) in others:
            dd=np.linalg.norm(p1-p2); L=lim(e1,e2)
            if dd<L: s+=(L-dd)**2*100+(L-dd)
    return s
def total_score(phis):
    built=[build_ipr_atoms(iP,d,phis[k]) for k,(iP,d) in enumerate(groups)]
    s=0.0
    for k in range(6):
        s+=clash(built[k], base)
        for m in range(k+1,6):
            s+=clash(built[k], built[m])
    return s

best_phis=None; best_s=1e18
for trial in range(3000):
    phis=list(rng.uniform(0,360,6))
    # local polish: a few sweeps
    for _ in range(3):
        for k in range(6):
            cand=[phis[k]+dphi for dphi in (0,60,-60,120,-120,180)]
            ss=[total_score(phis[:k]+[c%360]+phis[k+1:]) for c in cand]
            phis[k]=cand[int(np.argmin(ss))]%360
    s=total_score(phis)
    if s<best_s:
        best_s=s; best_phis=list(phis)
        if s<1e-6: break
print('best score:',round(best_s,4),'phis:',[round(p,1) for p in best_phis])

atoms=list(base)
for k,(iP,d) in enumerate(groups): atoms+=build_ipr_atoms(iP,d,best_phis[k])
el=[e for e,_ in atoms]; xyz=np.array([p for _,p in atoms])
rep=[]
for i in range(len(el)):
    for j in range(i+1,len(el)):
        dd=np.linalg.norm(xyz[i]-xyz[j]); L=lim(el[i],el[j])
        if dd<L and dd>0.01: rep.append((round(dd,2),el[i],i,el[j],j))
print('residual contacts:',sorted(rep)[:12])
with open('initial4.xyz','w') as f:
    f.write(f"{len(atoms)}\nCo2 anion v4\n")
    for e,p in atoms: f.write(f"{e} {p[0]:.5f} {p[1]:.5f} {p[2]:.5f}\n")
import json; json.dump(constraints,open('constraints4.json','w'))
print('atoms:',len(atoms))
